const std = @import("std");
const fourslash = @import("fourslash/fourslash.zig");

test "TestGoToDefinitionPreferSourceDefinition" {
    const content =
        \\// @Filename: /home/src/workspaces/project/a.js
        \\export const /*sourceTarget*/a = "a";
        \\// @Filename: /home/src/workspaces/project/a.d.ts
        \\export declare const /*dtsTarget*/a: string;
        \\// @Filename: /home/src/workspaces/project/index.ts
        \\import { a } from "./a";
        \\a/*start*/
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    _ = f.VerifyBaselineGoToDefinition(undefined, false, &.{"start"}) catch {};
    _ = f.VerifyBaselineGoToSourceDefinition(undefined, &.{"start"}) catch {};
    // f.Configure(undefined, .{.PreferGoToSourceDefinition = true});
    _ = f.VerifyBaselineGoToDefinition(undefined, false, &.{"start"}) catch {};
    // f.Configure(undefined, .{.PreferGoToSourceDefinition = true});
    _ = f.VerifyBaselineGoToDefinition(undefined, false, &.{"start"}) catch {};
}

test "TestQuickInfoJSDocLinkBackticks" {
    const content =
        \\// @noEmit: true
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @strict: true
        \\// @Filename: jsdocParseMatchingBackticks.js
        \\/**
        \\ * `{@link foo}` initial at-param is OK in title comment
        \\ * @param {string} x hi there `{@link foo}`
        \\ */
        \\export function f(x) {
        \\    return x/*x*/
        \\}
        \\f/*f*/
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    _ = f.GoToMarker(undefined, "f");
    _ = f.VerifyQuickInfoIs(undefined, "function f(x: string): string", "`{@link foo}` initial at-param is OK in title comment\n\n*@param* `x` — hi there `{@link foo}`") catch {};
    _ = f.GoToMarker(undefined, "x");
    _ = f.VerifyQuickInfoIs(undefined, "(parameter) x: string", "hi there `{@link foo}`") catch {};
}

