test "TestGoToDefinitionOverriddenMember24" {
    const content =
        \\// @strict: true
        \\// @target: esnext
        \\// @lib: esnext
        \\const prop: symbol = Symbol();
        \\
        \\abstract class A {
        \\  [prop]() {}
        \\}
        \\
        \\export class B extends A {
        \\  [|/*1*/override|] [prop]() {}
        \\}
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    _ = f.VerifyBaselineGoToDefinition(undefined, true, &.{"1"}) catch {};
}

