        \\a();
        \\interface b { a: number; }
        \\/** @deprecated */
        \\declare function b(): void
        \\declare const tb: b;
        \\[|b|]
        \\[|b|]();
        \\interface c { }
        \\/** @deprecated */
        \\declare function c(): void
        \\declare function c(a: number): void
