        \\    class Bar<B extends string> {
        \\        bar(param: B): void {}
        \\        baz(): this { return this; }
        \\    }
        \\    class Foo extends Bar<"foo"> {
        \\        foo(): this { return this; }
        \\    }
        \\    const b/*b1*/ = new Bar();
        \\    const f/*f4*/ = new Foo();
        \\}
        \\{
        \\    class Bar<B extends string> {
