        \\        bar: string;
        \\    }
        \\    var b: B<string>;
        \\    var r3 = b.foo; // number
        \\    var r/*2*/4 = b.b/*1*/ar; // string
        \\}
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    _ = f.GoToMarker(undefined, "1");
    _ = f.VerifyQuickInfoIs(undefined, "(property) B<string>.bar: string", "") catch {};
    _ = f.DeleteAtCaret(undefined, 1);
    _ = f.Insert(undefined, "z");
    _ = f.VerifyQuickInfoIs(undefined, "any", "") catch {};
    _ = f.VerifyNumberOfErrorsInCurrentFile(undefined, 1) catch {};
    _ = f.Backspace(undefined, 1);
    _ = f.Insert(undefined, "a");
    _ = f.VerifyQuickInfoIs(undefined, "(property) B<string>.bar: string", "") catch {};
    _ = f.GoToMarker(undefined, "2");
    _ = f.VerifyQuickInfoIs(undefined, "var r4: string", "") catch {};
    _ = f.VerifyNoErrors(undefined) catch {};
}

