test "TestIndentationInJsx3" {
    const content =
        \\//@Filename: file.tsx
        \\function foo() {
        \\   return (
        \\        <div>
        \\hello
        \\goodbye
        \\        </div>
        \\    )
        \\}
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    _ = f.VerifyCurrentFileContent(undefined, "function foo() {\n   return (\n        <div>\nhello\ngoodbye\n        </div>\n    )\n}") catch {};
    // f.FormatDocument(undefined, "");
