test "TestGetOccurrencesExport3" {
    const content =
        \\
        \\declare var x;
        \\[|export|] declare var y, z;
        \\
        \\namespace m {
        \\    export class C1 {
        \\        public pub1;
        \\        public pub2;
        \\        private priv1;
        \\        private priv2;
        \\        protected prot1;
        \\        protected prot2;
        \\
        \\        public public;
        \\        private private;
        \\        protected protected;
        \\
        \\        public constructor(public a, private b, protected c, public d, private e, protected f) {
        \\            this.public = 10;
        \\            this.private = 10;
        \\            this.protected = 10;
        \\        }
        \\
        \\        public get x() { return 10; }
        \\        public set x(value) { }
        \\
        \\        public static statPub;
        \\        private static statPriv;
        \\        protected static statProt;
        \\    }
        \\
        \\    export interface I1 {
        \\    }
        \\
        \\    export declare namespace ma.m1.m2.m3 {
        \\        interface I2 {
        \\        }
        \\    }
        \\
        \\    export namespace mb.m1.m2.m3 {
        \\        declare var foo;
        \\
        \\        export class C2 {
        \\            public pub1;
        \\            private priv1;
        \\            protected prot1;
        \\
        \\            protected constructor(public public, protected protected, private private) {
        \\            }
        \\        }
        \\    }
        \\
        \\    declare var ambientThing: number;
        \\    export var exportedThing = 10;
        \\    declare function foo(): string;
        \\}
        \\
        \\declare [|export|] var v1, v2;
        \\declare namespace dm { }
        \\[|export|] class EC { }
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    // f.VerifyBaselineDocumentHighlights(undefined, null , ToAny(f.Ranges()));
}

test "TestQuickInfoContextualTyping" {
    const content =
        \\// DEFAULT INTERFACES
        \\interface IFoo {
        \\    n: number;
        \\    s: string;
        \\    f(i: number, s: string): string;
        \\    a: number[];
        \\}
        \\interface IBar {
        \\    foo: IFoo;
        \\}
        \\// CONTEXT: Class property declaration
        \\class C1T5 {
        \\    /*1*/foo: (i: number, s: string) => number = function(/*2*/i) {
        \\        return /*3*/i;
        \\    }
        \\}
        \\// CONTEXT: Module property declaration
        \\namespace C2T5 {
        \\    export var /*4*/foo: (i: number, s: string) => number = function(/*5*/i) {
        \\        return /*6*/i;
        \\    }
        \\}
        \\// CONTEXT: Variable declaration
        \\var /*7*/c3t1: (s: string) => string = (function(/*8*/s) { return /*9*/s });
        \\var /*10*/c3t2 = <IFoo>({
        \\    n: 1
        \\})
        \\var /*11*/c3t3: number[] = [];
        \\var /*12*/c3t4: () => IFoo = function() { return <IFoo>({}) };
        \\var /*13*/c3t5: (n: number) => IFoo = function(/*14*/n) { return <IFoo>({}) };
        \\var /*15*/c3t6: (n: number, s: string) => IFoo = function(/*16*/n, /*17*/s) { return <IFoo>({}) };
        \\var /*18*/c3t7: {
        \\    (n: number): number;
        \\    (s1: string): number;
        \\};
        \\var /*20*/c3t8: (n: number, s: string) => number = function(/*21*/n) { return n; };
        \\var /*22*/c3t9: number[][] = [[],[]];
        \\var /*23*/c3t10: IFoo[] = [<IFoo>({}),<IFoo>({})];
        \\var /*24*/c3t11: {(n: number, s: string): string;}[] = [function(/*25*/n, /*26*/s) { return s; }];
        \\var /*27*/c3t12: IBar = {
        \\    /*28*/foo: <IFoo>({})
        \\}
        \\var /*29*/c3t13 = <IFoo>({
        \\    /*30*/f: function(/*31*/i, /*32*/s) { return s; }
        \\})
        \\var /*33*/c3t14 = <IFoo>({
        \\    /*34*/a: []
        \\})
        \\// CONTEXT: Class property assignment
        \\class C4T5 {
        \\    /*35*/foo: (i: number, s: string) => string;
        \\    constructor() {
        \\        this.foo = function(/*36*/i, /*37*/s) {
        \\            return s;
        \\        }
        \\    }
        \\}
        \\// CONTEXT: Module property assignment
        \\namespace C5T5 {
        \\    export var /*38*/foo: (i: number, s: string) => string;
        \\    foo = function(/*39*/i, /*40*/s) {
        \\        return s;
        \\    }
        \\}
        \\// CONTEXT: Variable assignment
        \\var /*41*/c6t5: (n: number) => IFoo;
        \\c6t5 = <(n: number) => IFoo>function(/*42*/n) { return <IFoo>({}) };
        \\// CONTEXT: Array index assignment
        \\var /*43*/c7t2: IFoo[];
        \\/*44*/c7t2[0] = <IFoo>({n: 1});
        \\// CONTEXT: Object property assignment
        \\interface IPlaceHolder {
        \\    t1: (s: string) => string;
        \\    t2: IFoo;
        \\    t3: number[];
        \\    t4: () => IFoo;
        \\    t5: (n: number) => IFoo;
        \\    t6: (n: number, s: string) => IFoo;
        \\    t7: {
        \\            (n: number, s: string): number;
        \\            //(s1: string, s2: string): number;
        \\        };
        \\    t8: (n: number, s: string) => number;
        \\    t9: number[][];
        \\    t10: IFoo[];
        \\    t11: {(n: number, s: string): string;}[];
        \\    t12: IBar;
        \\    t13: IFoo;
        \\    t14: IFoo;
        \\    }
        \\var objc8: {
        \\    t1: (s: string) => string;
        \\    t2: IFoo;
        \\    t3: number[];
        \\    t4: () => IFoo;
        \\    t5: (n: number) => IFoo;
        \\    t6: (n: number, s: string) => IFoo;
        \\    t7: {
        \\            (n: number, s: string): number;
        \\            //(s1: string, s2: string): number;
        \\        };
        \\    t8: (n: number, s: string) => number;
        \\    t9: number[][];
        \\    t10: IFoo[];
        \\    t11: {(n: number, s: string): string;}[];
        \\    t12: IBar;
        \\    t13: IFoo;
        \\    t14: IFoo;
        \\} = <IPlaceHolder>({});
        \\objc8./*45*/t1 = (function(/*46*/s) { return s });
        \\objc8./*47*/t2 = <IFoo>({
        \\    n: 1
        \\});
        \\objc8./*48*/t3 = [];
        \\objc8./*49*/t4 = function() { return <IFoo>({}) };
        \\objc8./*50*/t5 = function(/*51*/n) { return <IFoo>({}) };
