        \\var /*78*/c12t3 = <number[]> [];
        \\var /*79*/c12t4 = <() => IFoo> function() { return <IFoo>({}) };
        \\var /*80*/c12t5 = <(n: number) => IFoo> function(/*81*/n) { return <IFoo>({}) };
        \\var /*82*/c12t6 = <(n: number, s: string) => IFoo> function(/*83*/n, /*84*/s) { return <IFoo>({}) };
        \\var /*85*/c12t7 = <{
