        \\  prop1: stringWrapper() as Wrapper<"hello">,
        \\});
        \\
        \\type Unwrap<T extends Wrapper<any>> = T["_type"] extends Record<
        \\  string,
        \\  Wrapper<any>
        \\>
        \\  ? { [Key in keyof T["_type"]]: Unwrap<T["_type"][Key]> }
        \\  : T["_type"];
        \\
        \\type Test/*1*/ = Unwrap<typeof value>;
    ;

