        \\new [|/*newMyComponent*/MyComponent|]({});
        \\
        \\declare const /*MyComponent2*/MyComponent2: ComponentClass;
        \\<[|/*jsxMyComponent2*/MyComponent2|] />;
        \\new [|/*newMyComponent2*/MyComponent2|]();
        \\
        \\declare const /*MyComponent3*/MyComponent3: ComponentClass2;
