test "TestImportNameCodeFix_jsx5" {
    const content =
        \\// @lib: es5
        \\// @jsx: react
        \\// @module: esnext
        \\// @esModuleInterop: true
        \\// @moduleResolution: bundler
        \\// @Filename: /node_modules/react/index.d.ts
        \\export = React;
        \\export as namespace React;
        \\declare namespace React {
        \\    class Component {}
        \\}
        \\// @Filename: /node_modules/react-native/index.d.ts
        \\import * as React from "react";
        \\export class Text extends React.Component {};
        \\// @Filename: /a.tsx
        \\import React from "react";
        \\<[|Text|] />;
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    _ = f.GoToFile(undefined, "/a.tsx");
    _ = f.VerifyCodeFix(undefined, .{
        .Description = "Add import from \"react-native\"",
        .NewFileContent = "import React from \"react\";\nimport { Text } from \"react-native\";\n<Text />;",
        .Index = 0,
    }) catch {};
}

test "TestGetOccurrencesSuper" {
    const content =
        \\class SuperType {
        \\    superMethod() {
        \\    }
        \\
        \\    static superStaticMethod() {
        \\        return 10;
        \\    }
        \\}
        \\
        \\class SubType extends SuperType {
        \\    public  prop1 = [|s/**/uper|].superMethod;
        \\    private prop2 = [|super|].superMethod;
        \\
        \\    constructor() {
        \\        [|super|]();
        \\    }
        \\
        \\    public method1() {
        \\        return [|super|].superMethod();
        \\    }
        \\
        \\    private method2() {
        \\        return [|super|].superMethod();
        \\    }
        \\
        \\    public method3() {
        \\        var x = () => [|super|].superMethod();
        \\
        \\        // Bad but still gets highlighted
        \\        function f() {
        \\            [|super|].superMethod();
        \\        }
        \\    }
        \\
        \\    // Bad but still gets highlighted.
        \\    public static statProp1 = super.superStaticMethod;
        \\
        \\    public static staticMethod1() {
        \\        return super.superStaticMethod();
        \\    }
        \\
        \\    private static staticMethod2() {
        \\        return super.superStaticMethod();
        \\    }
        \\
        \\    // Are not actually 'super' keywords.
        \\    super = 10;
        \\    static super = 20;
        \\}
    ;

    const f = fourslash.NewFourslash(undefined, undefined, content);
    defer f.deinit();
    // f.VerifyBaselineDocumentHighlights(undefined, null , ToAny(f.Ranges()));
}

