        \\  *
        \\  *  param information first line
        \\  *
        \\  *  param information third line
        \\  */
        \\function /*j*/j(param1: string) { /*7*/param1 = "hello"; }
        \\/** 
        \\  * This is firstLine
        \\  * This is second Line
        \\  * @param param1 hello   @randomtag 
        \\  *
        \\  *  random information first line
        \\  *
        \\  *  random information third line
