        \\var v2: A | B = { b: 0, /*4*/common: 3 };
        \\
        \\// Function call
        \\function consumer(f:  A | B) { }
        \\consumer({ a: 0, b: 0, /*5*/common: 1 });
        \\
        \\// Type cast
        \\var c = <A | B> { /*6*/common: 0, b: 0 };
        \\
        \\// Array literal
